func (cmd *SSHCmd) jumpContainer(
	ctx context.Context,
	devsyConfig *config.Config,
	client client2.WorkspaceClient,
) error {
	// lock the workspace as long as we init the connection
	err := client.Lock(ctx)
	if err != nil {
		return err
	}
	defer client.Unlock()

	// start the workspace
	err = clientimplementation.StartWait(ctx, client, false)
	if err != nil {
