func (s *machineClient) Status(
	ctx context.Context,
	options client.StatusOptions,
) (client.Status, error) {
	stdout := &bytes.Buffer{}
	stderr := &bytes.Buffer{}

	err := s.executor.execute(ctx, execConfig{
		name:    "status",
		command: s.config.Exec.Status,
		stdout:  stdout,
		stderr:  io.MultiWriter(stderr, log.Writer(log.LevelInfo)),
	})
	if err != nil {
		return client.StatusNotFound, fmt.Errorf(
			"get status: %s%s",
			strings.TrimSpace(stdout.String()),
			strings.TrimSpace(stderr.String()),
		)
	}

	parsedStatus, err := client.ParseStatus(stdout.String())
	if err != nil {
		return client.StatusNotFound, err
	}

	return parsedStatus, nil
}

