#else

  static int access_flags[] = { O_RDONLY, O_WRONLY, O_RDWR, O_RDONLY };
  static int create_modes[] = {
    0,
    O_TRUNC,
    O_CREAT,
    O_CREAT | O_TRUNC,
    O_CREAT | O_EXCL
  };
  static int sync_flags[] = { 0, O_DSYNC, O_SYNC };

  int flags =
